// One compact trusted line per action — the SAME turn-input shape the
// Codex path renders, agent-generic: locator plus the standing-policy
// cue plus accepted role instructions, no discussion bodies or event-supplied
// instruction block.
export function promptText(envelope, action, roleInstructions = null,
                           launcher = null) {
	const participant = envelope.participant;
	let summary;
	if (action.kind === "work") {
		const state = action.claimed ? "claimed by you" : "ready and unclaimed";
		const name = action.local_id ?? action.work;
		const title = action.title ? ` (${action.title})` : "";
		summary = `v11 Work ${name}${title} is ${state} for ${participant}. Act through the canonical v11 CLI (detail work=${name}).`;
	} else if (action.kind === "obligation") {
		summary = `v11 @ obligation #${action.seq} on ${action.work} awaits ${participant}. Act through the canonical v11 CLI (obligations, respond/accept/dispose).`;
	} else if (action.kind === "poke") {
		// W5 slice B. Deliberately ordinary wording, matching the Codex
		// path word for word: the approved contract calls a poke a
		// lightweight request for status between collaborators, and
		// says it must not read as an alarm, an escalation, or an
		// automated health verdict. So it names who asked, repeats
		// their actual question, and points at the one verb that
		// answers it.
		summary = `${action.asker} asks ${participant}: ${action.request} Answer through the canonical v11 CLI (poke-answer poke=${action.poke} state=idle|working|waiting|needs-help explanation=…), reading your canonical Baton state first.`;

promptText(text) {
	const run = this.turn.then(async () => {
		this.policyFailure = null;
		const deadlineMs = this.config.turnTimeoutMs;
		const turnDone = this.connection.prompt({
			sessionId: this.sessionId,
			prompt: [{ type: "text", text }],
		});
		const death = this.exited.then((exit) => {
			throw new SessionSetupError(
				`the agent exited (${JSON.stringify(exit)}) `
				+ `mid-turn`);
		});
		let timer;
		const deadline = new Promise((_resolve, reject) => {
			timer = setTimeout(() => reject(new TurnDeadlineError(
				`configured ACP turn deadline exceeded `
				+ `(${deadlineMs}ms)`)), deadlineMs);
		});
		try {
			const response = await Promise.race(
				[turnDone, death, deadline]);
			if (this.policyFailure) throw this.policyFailure;
			return response;
		} finally {
			clearTimeout(timer);
		}
	});
	// The queue survives individual failures.

// bridge knows WHICH assignment episode the runner is
// about to serve. Correlation only — the Work table
// still decides who holds the claim.
correlation = {
	work: action.work, episode: action.episode_seq,
	session: live.sessionId ?? undefined };
await runtime.state("working", correlation);
await live.promptText(promptText(envelope, action,
                              role.instructions, launcher));
// W28681: THE DOMAIN DIES BEFORE THE TURN IS CALLED OVER.
// A prompt that returned says the model stopped talking;
// it says nothing about what its tools left running.
await settleDomain(`delivering ${action.action_key}`);
// W55705: A RETURNED PROMPT IS NOT A TERMINAL RESULT.
// ACP gives no semantic completion status, so the only
// thing this return proves is that the model stopped
// talking — equally consistent with a claim passed back,
// a claim still held, and a process killed mid-attempt.
// The canonical slot is read before anything advertises
// capacity, and a surviving claim fences the lane
// instead of publishing `idle` beside it.
const settlement = await settle.settle(action,
	{ session: correlation.session });
if (settlement === "stranded") {
	// The slot is occupied by something this offer cannot
	// become. Retain it and spend no turn.
	//
	// W55705 review (2026-09-01T03:41:20Z) [P1]: BREAK, NOT
	// CONTINUE. The outer fence check runs once per envelope,
	// so a `continue` here let the NEXT fresh action
	// revalidate against its own successful read and start a
	// turn — after this bridge had just concluded that the
	// participant's claim slot could not be proved safe. That
	// is fail-open for exactly the unreadable and drifted
	// cases the fence is for. Every remaining action is
	// retained: no prompt, no `markPresented`, no
	// `markWithdrawn`.
	failed = true;
	logger.warn(
		`${config.baton.participant}'s claim slot is stranded `
		+ `after ${action.action_key}; the rest of this `
		+ `envelope is retained and no further turn is spent`);

    }
    if (!message.is_error && lastAssistantModel !== null) {
        const activeTurnId = session.activeTurn?.promptUuid;
        await sessionFailures.clear((failure) => failure.recoveryPolicy === "real_model_success" ||
            (failure.severity === "warning" && failure.turnId === activeTurnId));
    }
    switch (message.subtype) {
        case "success": {
            if (message.result.includes("Please run /login")) {
                await failActiveWithSessionFailure("auth_required", RequestError.authRequired(), message.result);
                break;
            }
            if (message.stop_reason === "max_tokens") {
                stopReason = "max_tokens";
                break;
            }
            if (message.is_error) {
                await failActiveWithSessionFailure(providerFailureCategory(lastAssistantError, lastAssistantWasUsageLimit), internalErrorForClient(errorKindData(lastAssistantError), message.result), lastAssistantFailureTitle ?? message.result);
                break;
            }
            // The result text is forwarded in two cases. Local-only
            // commands (no model invocation): the result IS the command
            // output. Otherwise the result is normally a trailing copy of
            // text that already streamed — but a cache-replayed turn
            // generates no tokens, and some CLIs then skip streaming
            // entirely and answer on the `result` alone: no `stream_event`
            // deltas, no consolidated `assistant` message (issue #453).
            // Forward it rather than end the turn silently:
            // `deliveredAssistantText` covers whatever already reached the
            // client (a turn that showed its answer cannot emit it twice),
            // and the output-token check keeps the fallback to the
            // replayed turns it was reported for. `?? 0`: typed non-null,
            // but third-party backends have been observed omitting usage
            // token fields (see snapshotFromUsage), and the replay lane
            // was reported from exactly such a backend — treat a missing
            // count as the replay signature rather than silently disabling
            // the fallback there. (Autonomous results never get here —
            // they exit at the early break above — so no background
            // prose can be injected into the feed.)
            if (session.activeTurn?.isLocalOnlyCommand ||
                (!deliveredAssistantText && (message.usage.output_tokens ?? 0) === 0)) {
                for (const notification of toAcpNotifications(message.result, "assistant", params.sessionId, session.toolUseCache, this.client, this.logger)) {
                    await sendUpdate(notification);
                }
            }
            break;
        }
        case "error_during_execution": {
            if (message.stop_reason === "max_tokens") {
                stopReason = "max_tokens";
                break;
            }
            if (message.is_error) {
                await failActiveWithSessionFailure(providerFailureCategory(lastAssistantError, lastAssistantWasUsageLimit), internalErrorForClient(errorKindData(lastAssistantError), message.errors.join(", ") || message.subtype), lastAssistantFailureTitle ?? (message.errors.join(", ") || message.subtype));
                break;
            }
            stopReason = "end_turn";
            break;
        }
        case "error_max_budget_usd":
            if (message.is_error) {
                await failActiveWithSessionFailure("budget_exhausted", internalErrorForClient(errorKindData(lastAssistantError), message.errors.join(", ") || message.subtype), message.errors.join(", ") || message.subtype);
                break;
            }
            stopReason = "max_turn_requests";
            break;
        case "error_max_turns":
            if (message.is_error) {
                await failActiveWithSessionFailure("context_exhausted", internalErrorForClient(errorKindData(lastAssistantError), message.errors.join(", ") || message.subtype), message.errors.join(", ") || message.subtype);
                break;
            }
            stopReason = "max_turn_requests";
            break;
        case "error_max_structured_output_retries":
            if (message.is_error) {
                await failActiveWithSessionFailure("provider_error", internalErrorForClient(errorKindData(lastAssistantError), message.errors.join(", ") || message.subtype), message.errors.join(", ") || message.subtype);
                break;
            }
            stopReason = "max_turn_requests";
            break;
        default:
            unreachable(message, this.logger);
            break;
    }
    // Settle the user turn at its terminal result so the client unlocks
    // as soon as the answer is done, rather than waiting for the SDK's
    // trailing `idle` (which can lag while background work runs — issue
    // #773). The consumer keeps draining afterward (absorbing idle and
    // forwarding any background output).
    //
    // One exception: while background subagents this turn spawned are
    // still live, settling now would strand their remaining work
    // outside any turn — ACP allows out-of-turn session/update, but
    // many clients stop consuming at the prompt response, and a
    // subagent's permission request would block on an RPC nobody
    // answers (issues #864/#866). Hold the turn open instead: store
    // the outcome and settle with it once the subagents are done —
    // at their followup's terminal result (see the deferred-settle
    // block above the subtype switch) or at an idle with none of
    // them left — so the subagents' streamed output, their
    // permission requests, and the model's promised summary all land
    // inside the turn. `session/cancel` and the next prompt's echo
    // hand-off still settle a deferred turn early, so a long-running
    // subagent never holds the prompt hostage.
    //
    // is_error/auth already settled via failActive (activeTurn is null
    // then, so both branches no-op); cancellation is left to the
    // idle/abort path. settleActive is idempotent, so a duplicate
    // idle is a no-op.
    if (!session.cancelled) {
        settleOrDefer({ stopReason, usage: sessionUsage(session) });
    }
}
